     1	package com.loja.orderservice.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	
     6	public class PricingUtil {
     7	    private static final int SCALE = 2;
     8	
     9	    public static BigDecimal round(BigDecimal value) {
    10	        if (value == null) {
    11	            return BigDecimal.ZERO;
    12	        }
    13	        return value.setScale(SCALE, RoundingMode.HALF_EVEN);
    14	    }
    15	
    16	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
    17	        return round(a.add(b));
    18	    }
    19	
    20	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
    21	        return round(a.subtract(b));
    22	    }
    23	
    24	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
    25	        return round(a.multiply(b));
    26	    }
    27	
    28	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
    29	        return round(a.divide(b, SCALE, RoundingMode.HALF_EVEN));
    30	    }
    31	
    32	    public static BigDecimal percentage(BigDecimal base, BigDecimal percent) {
    33	        return round(base.multiply(percent).divide(new BigDecimal("100"), SCALE, RoundingMode.HALF_EVEN));
    34	    }
    35	
    36	    public static int ceilDays(double hours) {
    37	        return (int) Math.ceil(hours / 24.0);
    38	    }
    39	}
