     1	package com.loja.orderservice.service;
     2	
     3	import com.loja.orderservice.dto.CustomerDTO;
     4	import com.loja.orderservice.dto.OrderItemDTO;
     5	import com.loja.orderservice.dto.OrderRequestDTO;
     6	import com.loja.orderservice.entity.*;
     7	import com.loja.orderservice.exception.OrderException;
     8	import com.loja.orderservice.repository.OrderRepository;
     9	import com.loja.orderservice.repository.ProductRepository;
    10	import org.springframework.http.HttpStatus;
    11	import org.springframework.stereotype.Service;
    12	
    13	import java.util.HashSet;
    14	import java.util.List;
    15	import java.util.Optional;
    16	import java.util.Set;
    17	
    18	@Service
    19	public class ValidationService {
    20	    private final ProductRepository productRepository;
    21	    private final OrderRepository orderRepository;
    22	
    23	    public ValidationService(ProductRepository productRepository, OrderRepository orderRepository) {
    24	        this.productRepository = productRepository;
    25	        this.orderRepository = orderRepository;
    26	    }
    27	
    28	    public void validateOrderRequest(OrderRequestDTO request) {
    29	        // 1. Validate items, customer, and basic structure
    30	        validateItemsAndCustomer(request);
    31	
    32	        // 2. Check if products exist and valid
    33	        validateProducts(request.getItems());
    34	
    35	        // 3. Check club tier
    36	        validateClubTier(request.getClubTier());
    37	
    38	        // 4. Check region
    39	        validateRegion(request.getRegion());
    40	
    41	        // 5. Check zip code
    42	        validateZipCode(request.getZipCode());
    43	
    44	        // 6. Check shipping method
    45	        validateShippingMethod(request.getShippingMethod());
    46	
    47	        // 7. Check payment method
    48	        validatePaymentMethod(request.getPaymentMethod());
    49	
    50	        // 8. Check installments
    51	        validateInstallments(request.getPaymentMethod(), request.getInstallments());
    52	
    53	        // 9. Validate payment method availability
    54	        validatePaymentMethodAvailability(request);
    55	
    56	        // 10. Validate coupon
    57	        validateCoupon(request, request.getItems());
    58	    }
    59	
    60	    private void validateItemsAndCustomer(OrderRequestDTO request) {
    61	        if (request.getItems() == null || request.getItems().isEmpty()) {
    62	            throw new OrderException("INVALID_ORDER", "Cart is empty", HttpStatus.UNPROCESSABLE_ENTITY);
    63	        }
    64	
    65	        CustomerDTO customer = request.getCustomer();
    66	        if (customer == null || customer.getCpf() == null || customer.getEmail() == null) {
    67	            throw new OrderException("INVALID_ORDER", "Customer CPF and email are required", HttpStatus.UNPROCESSABLE_ENTITY);
    68	        }
    69	
    70	        Set<String> seenSkus = new HashSet<>();
    71	        for (OrderItemDTO item : request.getItems()) {
    72	            if (item.getSku() == null) {
    73	                throw new OrderException("INVALID_ORDER", "Item SKU is required", HttpStatus.UNPROCESSABLE_ENTITY);
    74	            }
    75	
    76	            if (seenSkus.contains(item.getSku())) {
    77	                throw new OrderException("INVALID_ORDER", "Duplicate SKU in cart", HttpStatus.UNPROCESSABLE_ENTITY);
    78	            }
    79	            seenSkus.add(item.getSku());
    80	
    81	            if (item.getQuantity() == null || item.getQuantity() <= 0) {
    82	                throw new OrderException("INVALID_ORDER", "Quantity must be positive", HttpStatus.UNPROCESSABLE_ENTITY);
    83	            }
    84	        }
    85	    }
    86	
    87	    private void validateProducts(List<OrderItemDTO> items) {
    88	        for (OrderItemDTO item : items) {
    89	            Optional<Product> product = productRepository.findById(item.getSku());
    90	
    91	            if (product.isEmpty()) {
    92	                throw new OrderException("UNKNOWN_PRODUCT", "Product not found: " + item.getSku(), HttpStatus.UNPROCESSABLE_ENTITY);
    93	            }
    94	
    95	            Product p = product.get();
    96	            if (p.isDiscontinued()) {
    97	                throw new OrderException("PRODUCT_DISCONTINUED", "Product is discontinued: " + item.getSku(), HttpStatus.UNPROCESSABLE_ENTITY);
    98	            }
    99	
   100	            if (p.getStock() < item.getQuantity()) {
   101	                throw new OrderException("INSUFFICIENT_STOCK", "Insufficient stock for: " + item.getSku(), HttpStatus.UNPROCESSABLE_ENTITY);
   102	            }
   103	        }
   104	    }
   105	
   106	    private void validateClubTier(ClubTier tier) {
   107	        if (tier == null) {
   108	            throw new OrderException("INVALID_CLUB_TIER", "Club tier is required", HttpStatus.UNPROCESSABLE_ENTITY);
   109	        }
   110	        try {
   111	            ClubTier.valueOf(tier.toString());
   112	        } catch (IllegalArgumentException e) {
   113	            throw new OrderException("INVALID_CLUB_TIER", "Invalid club tier", HttpStatus.UNPROCESSABLE_ENTITY);
   114	        }
   115	    }
   116	
   117	    private void validateRegion(Region region) {
   118	        if (region == null) {
   119	            throw new OrderException("INVALID_REGION", "Region is required", HttpStatus.UNPROCESSABLE_ENTITY);
   120	        }
   121	    }
   122	
   123	    private void validateZipCode(String zipCode) {
   124	        if (zipCode == null || zipCode.length() != 8 || !zipCode.matches("\\d{8}")) {
   125	            throw new OrderException("INVALID_ZIP_CODE", "Invalid ZIP code format", HttpStatus.UNPROCESSABLE_ENTITY);
   126	        }
   127	    }
   128	
   129	    private void validateShippingMethod(ShippingMethod method) {
   130	        if (method == null) {
   131	            throw new OrderException("INVALID_SHIPPING_METHOD", "Shipping method is required", HttpStatus.UNPROCESSABLE_ENTITY);
   132	        }
   133	    }
   134	
   135	    private void validatePaymentMethod(PaymentMethod method) {
   136	        if (method == null) {
   137	            throw new OrderException("INVALID_PAYMENT_METHOD", "Payment method is required", HttpStatus.UNPROCESSABLE_ENTITY);
   138	        }
   139	    }
   140	
   141	    private void validateInstallments(PaymentMethod method, Integer installments) {
   142	        int inst = installments != null ? installments : 1;
   143	
   144	        if (method == PaymentMethod.PIX || method == PaymentMethod.BANK_SLIP) {
   145	            if (inst != 1) {
   146	                throw new OrderException("INVALID_INSTALLMENTS", "PIX and BANK_SLIP only support 1 installment", HttpStatus.UNPROCESSABLE_ENTITY);
   147	            }
   148	        } else if (method == PaymentMethod.CREDIT_CARD) {
   149	            if (inst < 1 || inst > 12) {
   150	                throw new OrderException("INVALID_INSTALLMENTS", "Credit card supports 1-12 installments", HttpStatus.UNPROCESSABLE_ENTITY);
   151	            }
   152	        }
   153	    }
   154	
   155	    private void validatePaymentMethodAvailability(OrderRequestDTO request) {
   156	        if (request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
   157	            // Will check total in PricingService
   158	        }
   159	    }
   160	
   161	    private void validateCoupon(OrderRequestDTO request, List<OrderItemDTO> items) {
   162	        String coupon = request.getCoupon();
   163	        if (coupon != null && !coupon.isEmpty()) {
   164	            if (!isValidCoupon(coupon)) {
   165	                throw new OrderException("INVALID_COUPON", "Invalid coupon code", HttpStatus.UNPROCESSABLE_ENTITY);
   166	            }
   167	
   168	            validateCouponApplicability(coupon, request, items);
   169	        }
   170	    }
   171	
   172	    private boolean isValidCoupon(String coupon) {
   173	        return coupon.equals("WELCOME10") || coupon.equals("MINUS50") ||
   174	               coupon.equals("FREESHIPPING") || coupon.equals("BUY3PAY2");
   175	    }
   176	
   177	    public void validateCouponApplicability(String coupon, OrderRequestDTO request, List<OrderItemDTO> items) {
   178	        if (coupon == null || coupon.isEmpty()) {
   179	            return;
   180	        }
   181	
   182	        if ("WELCOME10".equals(coupon)) {
   183	            List<Order> completedOrders = orderRepository.findCompletedOrdersByCpf(request.getCustomer().getCpf());
   184	            if (!completedOrders.isEmpty()) {
   185	                throw new OrderException("COUPON_NOT_APPLICABLE", "WELCOME10 only for first purchase", HttpStatus.UNPROCESSABLE_ENTITY);
   186	            }
   187	        }
   188	
   189	        if ("FREESHIPPING".equals(coupon)) {
   190	            if (request.getShippingMethod() == ShippingMethod.STORE_PICKUP) {
   191	                throw new OrderException("COUPON_NOT_APPLICABLE", "FREESHIPPING not valid for STORE_PICKUP", HttpStatus.UNPROCESSABLE_ENTITY);
   192	            }
   193	        }
   194	    }
