   242	    private PaymentAdjustmentInfo calculatePaymentAdjustment(PaymentMethod method, BigDecimal subtotal, Integer installments, boolean hasCoupon) {
   243	        int inst = installments != null ? installments : 1;
   244	        BigDecimal adjustment = BigDecimal.ZERO;
   245	        BigDecimal finalTotal = subtotal;
   246	
   247	        if (method == PaymentMethod.PIX && !hasCoupon) {
   248	            BigDecimal discount = PricingUtil.percentage(subtotal, new BigDecimal("5"));
   249	            adjustment = discount.negate();
   250	            finalTotal = PricingUtil.subtract(subtotal, discount);
   251	        } else if (method == PaymentMethod.BANK_SLIP) {
   252	            adjustment = new BigDecimal("3.49");
   253	            finalTotal = PricingUtil.add(subtotal, adjustment);
   254	        } else if (method == PaymentMethod.CREDIT_CARD) {
   255	            if (inst <= 3) {
   256	                finalTotal = subtotal;
   257	                adjustment = BigDecimal.ZERO;
   258	            } else {
   259	                BigDecimal monthlyRate = new BigDecimal("0.0199");
   260	                BigDecimal multiplier = calculateInstallmentMultiplier(monthlyRate, inst);
   261	                BigDecimal installmentValue = PricingUtil.multiply(subtotal, multiplier);
   262	                finalTotal = PricingUtil.multiply(installmentValue, new BigDecimal(inst));
   263	                adjustment = PricingUtil.subtract(finalTotal, subtotal);
   264	            }
   265	        }
   266	
   267	        BigDecimal installmentAmount = PricingUtil.divide(finalTotal, new BigDecimal(inst));
   268	
   269	        return new PaymentAdjustmentInfo(finalTotal, adjustment, inst, installmentAmount);
